import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { existsSync, mkdtempSync, writeFileSync, readFileSync, rmSync, mkdirSync, symlinkSync, readlinkSync, chmodSync, statSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { SqliteStore } from "../../electron/persistence/sqlite-store";
import { createWorkspaceCleanupRuntime } from "../../electron/host-service/workspace-cleanup-runtime";
import { workspaceExecutionGate } from "../../electron/shared/workspace-execution-gate";

async function main() {
  const root = mkdtempSync(join(tmpdir(), "archive-snapshot-"));
  const git = (cwd: string, ...args: string[]) => execFileSync("git", args, { cwd, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] });
  let store: SqliteStore | undefined;
  try {
    const repo = join(root, "repository");
    const path = join(root, "feature");
    git(root, "init", "-b", "main", repo);
    writeFileSync(join(repo, ".gitignore"), "ignored\n");
    // A required pointer filter proves capture uses clean filters and restore uses smudge filters.
    writeFileSync(join(repo, ".gitattributes"), "*.ptr filter=pointer\n");
    writeFileSync(join(repo, "tracked"), "original\n");
    writeFileSync(join(repo, "removed"), "delete me\n");
    writeFileSync(join(repo, "executable"), "mode bytes\n");
    const marker = join(root, "smudge-fails");
    git(repo, "config", "filter.pointer.clean", "sed -e 's/^/pointer:/'");
    git(repo, "config", "filter.pointer.smudge", `test ! -e '${marker}' && sed -e 's/^pointer://'`);
    git(repo, "config", "filter.pointer.required", "true");
    git(repo, "add", ".");
    git(repo, "-c", "user.name=Test", "-c", "user.email=test@example.test", "-c", "commit.gpgsign=false", "commit", "-m", "test: original state");
    git(root, "init", "--bare", join(root, "remote.git"));
    git(repo, "remote", "add", "origin", join(root, "remote.git"));
    git(repo, "push", "-u", "origin", "main");
    git(repo, "worktree", "add", "-b", "feature", path);
    store = new SqliteStore({ dbPath: join(root, "state.sqlite"), runMaintenance: false });
    store.upsertWorkspace({ id: "feature", name: "Feature", snapshot: { activeTaskId: null, tasks: [], messagesByTask: {} } });
    store.saveRepositoryRegistry({ repositories: [{ repositoryPath: repo, repositoryName: "Repository", lastOpenedAt: "2026-01-01", defaultBranch: "main", workspaces: [{ id: "base", name: "Default", updatedAt: "2026-01-01" }, { id: "feature", name: "Feature", updatedAt: "2026-01-01" }], activeWorkspaceId: "base", workspacePathById: { base: repo, feature: path }, workspaceBranchById: { base: "main", feature: "feature" }, workspaceDefaultById: { base: true, feature: false } }] });
    const runtime = createWorkspaceCleanupRuntime({ store: () => store!, hasTerminals: () => false, pr: async () => ({ ok: true, pr: null, stderr: "" }) });
    const act = (action: "archive" | "restore" | "delete", saveChanges = false) => runtime.act({ action, workspaceId: "feature", repositoryPath: repo, ...(saveChanges ? { saveChanges: true } : {}) });
    const manualArchive = () => runtime.act({ action: "archive", workspaceId: "feature", repositoryPath: repo, preserveLocalWork: true, saveChanges: true });
    const keepArchive = () => runtime.act({ action: "archive", workspaceId: "feature", repositoryPath: repo, preserveLocalWork: true, keepWorktree: true });
    for (const flag of ["assume-unchanged", "skip-worktree"]) {
      git(path, "update-index", `--${flag}`, "tracked");
      writeFileSync(join(path, "tracked"), "keep hidden changes\n");
      assert.equal((await manualArchive()).reason, "hiddenChanges");
      assert.equal((await keepArchive()).ok, true);
      assert.equal((await runtime.list()).rows.find(row => row.id === "feature")?.keptWorktree, true);
      assert.equal((await act("delete")).reason, "keptWorktree");
      assert.equal((await runtime.act({ action: "removeWorktree", workspaceId: "feature", repositoryPath: repo })).reason, "keptWorktree");
      assert.equal((await act("restore")).ok, true);
      assert.equal(readFileSync(join(path, "tracked"), "utf8"), "keep hidden changes\n");
      git(path, "update-index", `--no-${flag}`, "tracked");
      git(path, "restore", "tracked");
    }
    // Keeping files on disk retains Git-ignored files, including across a SQLite restart.
    writeFileSync(join(path, "ignored"), "kept on disk");
    assert.equal((await keepArchive()).ok, true);
    store.close(); store = new SqliteStore({ dbPath: join(root, "state.sqlite"), runMaintenance: false });
    assert.equal((await runtime.list()).rows.find(row => row.id === "feature")?.keptWorktree, true, "The kept checkout survives a SQLite restart");
    assert.equal((await act("restore")).ok, true);
    assert.equal(readFileSync(join(path, "ignored"), "utf8"), "kept on disk");
    rmSync(join(path, "ignored"));
    const dirty = () => {
      writeFileSync(join(path, "tracked"), "staged\n"); git(path, "add", "tracked");
      writeFileSync(join(path, "tracked"), "unstaged\r\nbytes\n");
      writeFileSync(join(path, "untracked"), Buffer.from([0, 255, 13, 10, 22]));
      writeFileSync(join(path, "payload.ptr"), "large payload\n");
      rmSync(join(path, "removed"));
      writeFileSync(join(path, "index-only"), "staged only\n"); git(path, "add", "index-only"); rmSync(join(path, "index-only"));
      symlinkSync("tracked", join(path, "untracked-link"));
      chmodSync(join(path, "executable"), 0o755);
    };
    dirty();
    const status = git(path, "status", "--porcelain=v1", "-uall");
    const index = git(path, "show", ":tracked");
    const branch = git(repo, "rev-parse", "refs/heads/feature");
    assert.equal((await act("archive")).ok, false, "Default archive still blocks changed files");
    assert.equal((await runtime.list()).rows.find(row => row.id === "feature")!.canSaveChanges, true, JSON.stringify((await runtime.list()).rows));
    // A failed durable save must leave the full checkout and active registry intact.
    const archive = store.archiveWorkspacePersistence.bind(store);
    store.archiveWorkspacePersistence = () => { throw new Error("fixtureSaveFailure"); };
    assert.equal((await act("archive", true)).ok, false);
    store.archiveWorkspacePersistence = archive;
    assert.equal(existsSync(path), true);
    assert.equal(git(path, "status", "--porcelain=v1", "-uall"), status);
    assert.equal(git(path, "show", ":tracked"), index);
    assert.equal(store.listArchivedWorkspacesPersistence().length, 0);
    mkdirSync(join(repo, ".git", "refs", "stave"), { recursive: true });
    writeFileSync(join(repo, ".git", "refs", "stave", "archives"), "blocked namespace");
    const failedSave = await act("archive", true);
    assert.equal(failedSave.ok, false);
    assert.equal(failedSave.reason, "savedChangesGitFailed");
    assert.equal(git(path, "status", "--porcelain=v1", "-uall"), status);
    assert.equal(store.listArchivedWorkspacesPersistence().length, 0);
    rmSync(join(repo, ".git", "refs", "stave", "archives"));
    store.archiveWorkspacePersistence = args => { const record = archive(args); writeFileSync(join(path, "late-file"), "concurrent write"); return record; };
    const changedDuringSave = await act("archive", true);
    store.archiveWorkspacePersistence = archive;
    assert.equal(changedDuringSave.ok, false);
    assert.equal(changedDuringSave.reason, "savedChangesChangedDuringSave");
    assert.equal(readFileSync(join(path, "late-file"), "utf8"), "concurrent write");
    assert.equal(store.listArchivedWorkspacesPersistence().length, 0);
    rmSync(join(path, "late-file"));
    assert.equal(git(path, "status", "--porcelain=v1", "-uall"), status);
    git(repo, "worktree", "lock", path);
    const locked = await act("archive", true);
    assert.equal(locked.ok, false);
    assert.equal(locked.reason, "worktreeRemoveFailed");
    assert.equal(git(path, "status", "--porcelain=v1", "-uall"), status);
    assert.equal(git(path, "show", ":tracked"), index);
    assert.equal(store.listArchivedWorkspacesPersistence().length, 0);
    git(repo, "worktree", "unlock", path);
    const mergeHead = git(path, "rev-parse", "--path-format=absolute", "--git-path", "MERGE_HEAD").trim();
    writeFileSync(mergeHead, branch);
    assert.equal((await manualArchive()).reason, "gitOperationInProgress");
    assert.equal(readFileSync(mergeHead, "utf8"), branch);
    rmSync(mergeHead);

    const localCommit = git(repo, "-c", "user.name=Test", "-c", "user.email=test@example.test", "-c", "commit.gpgsign=false",
      "commit-tree", "-p", branch.trim(), "-m", "test: local-only commit", `${branch.trim()}^{tree}`);
    git(repo, "update-ref", "refs/heads/feature", localCommit.trim());
    assert.match((await act("archive", true)).reason ?? "", /unpushedCommits/, "The strict path keeps rejecting local-only commits");
    const request = { action: "archive", workspaceId: "feature", repositoryPath: repo, preserveLocalWork: true, saveChanges: true } as const;
    assert.match((await runtime.act({ ...request, deleteBranch: true })).reason ?? "", /unpushedCommits/);
    assert.match((await runtime.act(request, true)).reason ?? "", /unpushedCommits/);
    assert.equal(git(path, "status", "--porcelain=v1", "-uall"), status);
    // Git-ignored files are disposable and removed with the checkout, as automatic cleanup does.
    writeFileSync(join(path, "ignored"), "regenerable output");
    const archived = await manualArchive();
    assert.equal(archived.ok, true, JSON.stringify(archived));
    assert.equal(existsSync(path), false);
    const ref = store.listArchivedWorkspacesPersistence()[0]!.savedChangesRef!;
    assert.match(ref, /^refs\/stave\/archives\//);
    assert.equal(git(repo, "rev-parse", "refs/heads/feature"), localCommit);
    assert.ok(!git(repo, "ls-tree", "-r", "--name-only", ref).split("\n").includes("ignored"));
    assert.equal(git(repo, "cat-file", "-p", `${ref}:payload.ptr`), "pointer:large payload\n", "Capture stores the clean-filtered pointer");
    assert.equal((await runtime.list()).rows.find(row => row.id === "feature")!.savedChanges, true);
    store.close(); store = new SqliteStore({ dbPath: join(root, "state.sqlite"), runMaintenance: false });
    assert.equal(store.listArchivedWorkspacesPersistence()[0]!.savedChangesRef, ref, "Snapshot ref survives SQLite restart");
    mkdirSync(path); writeFileSync(join(path, "occupied"), "keep existing");
    const conflict = await act("restore");
    assert.equal(conflict.ok, false);
    assert.equal(conflict.reason, "savedChangesRestoreFilesExist");
    assert.equal(readFileSync(join(path, "occupied"), "utf8"), "keep existing");
    rmSync(path, { recursive: true });
    const archivedIntact = () => {
      assert.equal(store!.listArchivedWorkspacesPersistence()[0]?.savedChangesRef, ref, "Archive record keeps its saved changes");
      assert.equal(git(repo, "rev-parse", "--verify", "--quiet", ref).trim().length, 40, "Saved changes ref remains");
      assert.equal(existsSync(path), false, "No partial checkout remains");
      assert.ok(!git(repo, "worktree", "list", "--porcelain").includes(path), "No worktree remains registered");
    };
    const identity = ["-c", "user.name=Test", "-c", "user.email=test@example.test", "-c", "commit.gpgsign=false"];
    const moved = git(repo, ...identity, "commit-tree", "-p", localCommit.trim(), "-m", "test: moved", `${localCommit.trim()}^{tree}`).trim();
    git(repo, "update-ref", "refs/heads/feature", moved);
    const branchMoved = await act("restore");
    assert.equal(branchMoved.ok, false);
    assert.equal(branchMoved.reason, "savedChangesRestoreBranchMoved");
    archivedIntact();
    git(repo, "update-ref", "refs/heads/feature", localCommit.trim());
    // Apply fails after the worktree is created; the restore rolls back so a retry can run.
    writeFileSync(marker, "");
    const applyFailed = await act("restore");
    assert.equal(applyFailed.ok, false);
    assert.equal(applyFailed.reason, "savedChangesRestoreGitFailed");
    archivedIntact();
    assert.equal(git(repo, "rev-parse", "refs/heads/feature"), localCommit);
    git(repo, "branch", "-D", "feature");
    const recreatedFailed = await act("restore");
    assert.equal(recreatedFailed.reason, "savedChangesRestoreGitFailed");
    archivedIntact();
    assert.equal(git(repo, "for-each-ref", "--format=%(refname)", "refs/heads/feature"), "", "A branch recreated by the failed restore is removed again");
    // A file the snapshot does not own makes the rollback unprovable, so the checkout is kept.
    const hook = join(repo, ".git", "hooks", "post-checkout");
    writeFileSync(hook, "#!/bin/sh\necho foreign > unrelated\n"); chmodSync(hook, 0o755);
    const partial = await act("restore");
    rmSync(hook);
    assert.equal(partial.reason, "savedChangesRestorePartial");
    assert.equal(readFileSync(join(path, "unrelated"), "utf8"), "foreign\n");
    assert.equal(store.listArchivedWorkspacesPersistence()[0]?.savedChangesRef, ref);
    git(repo, "worktree", "remove", "--force", path);
    rmSync(marker);
    // A blocked ref deletion after the restore is durable must not fail the restore or keep execution stopped.
    const lock = join(repo, ".git", `${ref}.lock`);
    writeFileSync(lock, "");
    assert.ok(workspaceExecutionGate.snapshot().some(state => state.workspaceId === "feature"), "Archive stopped execution");
    const warnings: unknown[][] = [];
    const warn = console.warn;
    console.warn = (...args: unknown[]) => { warnings.push(args); };
    const restored = await act("restore").finally(() => { console.warn = warn; });
    assert.equal(restored.ok, true, JSON.stringify(restored));
    assert.equal(warnings.length, 1, "The deferred ref deletion is logged");
    assert.equal(workspaceExecutionGate.snapshot().some(state => state.workspaceId === "feature"), false, "Restore resumes execution");
    assert.equal(store.listArchivedWorkspacesPersistence().length, 0);
    assert.equal(git(repo, "rev-parse", "--verify", "--quiet", ref).trim().length, 40, "Blocked ref deletion is deferred");
    rmSync(lock);
    assert.equal(store.listArchivedWorkspacesPersistence().length, 0);
    assert.equal(git(repo, "rev-parse", "refs/heads/feature"), localCommit);
    assert.equal(readFileSync(join(path, "payload.ptr"), "utf8"), "large payload\n", "Restore applies the smudge filter");
    assert.equal(git(path, "status", "--porcelain=v1", "-uall"), status);
    assert.equal(git(path, "show", ":tracked"), index);
    assert.equal(readFileSync(join(path, "tracked"), "utf8"), "unstaged\r\nbytes\n");
    assert.deepEqual(readFileSync(join(path, "untracked")), Buffer.from([0, 255, 13, 10, 22]));
    assert.equal(existsSync(join(path, "ignored")), false);
    assert.equal(existsSync(join(path, "removed")), false);
    assert.equal(existsSync(join(path, "index-only")), false);
    assert.equal(git(path, "show", ":index-only"), "staged only\n");
    assert.equal(readlinkSync(join(path, "untracked-link")), "tracked");
    assert.equal(statSync(join(path, "executable")).mode & 0o111, 0o111);
    // Git drops its worktree record even when it cannot delete an ignored file. The
    // leftover folder is not a checkout, so the archive must stay instead of reactivating it.
    const leftover = async (saved: boolean) => {
      mkdirSync(join(path, "ignored")); writeFileSync(join(path, "ignored", "read-only"), "cache");
      chmodSync(join(path, "ignored"), 0o555);
      const result = await manualArchive();
      chmodSync(join(path, "ignored"), 0o755);
      assert.equal(result.ok, false);
      assert.equal(result.reason, "worktreeLeftoverFiles");
      const record = store!.listArchivedWorkspacesPersistence()[0];
      assert.ok(record, "The archive stays");
      assert.equal(Boolean(record.savedChangesRef), saved);
      assert.ok(!store!.loadRepositoryRegistry()[0]!.workspaces.some(workspace => workspace.id === "feature"), "The leftover folder is not reactivated");
      assert.ok(!git(repo, "worktree", "list", "--porcelain").includes(path), "Git no longer lists the checkout");
      assert.equal(readFileSync(join(path, "ignored", "read-only"), "utf8"), "cache");
      assert.equal((await act("restore")).ok, false, "Restore waits for the leftover folder to be deleted");
      rmSync(path, { recursive: true });
      const restoredAfterLeftover = await act("restore");
      assert.equal(restoredAfterLeftover.ok, true, JSON.stringify(restoredAfterLeftover));
    };
    await leftover(true);
    assert.equal(git(path, "status", "--porcelain=v1", "-uall"), status, "Saved changes survive the leftover folder");
    assert.equal(git(path, "show", ":tracked"), index);
    git(path, "reset", "--hard"); git(path, "clean", "-fd");
    assert.equal(git(path, "status", "--porcelain=v1", "-uall"), "");
    await leftover(false);
    assert.equal(git(path, "status", "--porcelain=v1", "-uall"), "");
    writeFileSync(join(path, "untracked"), "archive again");
    const again = await manualArchive(); assert.equal(again.ok, true, JSON.stringify(again));
    const deletedRef = store.listArchivedWorkspacesPersistence()[0]!.savedChangesRef!;
    git(repo, "push", "origin", "feature");
    const deleted = await act("delete"); assert.equal(deleted.ok, true, JSON.stringify(deleted));
    assert.equal(git(repo, "for-each-ref", "--format=%(refname)", deletedRef), "");
    assert.equal(store.loadWorkspaceSnapshot({ workspaceId: "feature" }), null);
  } finally {
    store?.close(); workspaceExecutionGate.setArchiveReader(() => []); workspaceExecutionGate.resume("feature");
    rmSync(root, { recursive: true, force: true });
  }
}
main().catch(error => { console.error(error); process.exitCode = 1; });
